/** the plant in a few facts, each with its source */
/** `differsAt`: where the sources of an entry DISAGREE (its note says so), the places in `sources` of the ones on the other side: the card then shows the first source and these, so that a reader can open both sides */
export const FACTS: ReadonlyArray<{ label: string; value: string; sources: Source[]; note?: string; differsAt?: number[] }> = [
  { label: "Technology came from", value: "Britain: the Indian Steel Works Construction Company (ISCON), a consortium of British companies (Rourkela's technology came from Germany, Bhilai's from the USSR)", sources: [city(65, "With the earlier steel plants being aided by Germany and the USSR, respectively, the Government of India looked towards Britain to support the Durgapur project.")] },
  { label: "Where", value: "Durgapur, West Bengal, on the banks of the Damodar River, on the Grand Trunk Road (NH-19) and the Kolkata-Delhi main line. SAIL gives its distance from Kolkata as 158 km; road distances quoted elsewhere are longer, about 170 to 180 km", sources: [on(SRC.about, "located at a distance of 158 KM from Kolkata"), on(SRC.about, "NH-19 (erstwhile GT road)")] },
  { label: "Its place", value: "the third integrated steel plant of Hindustan Steel Limited, after Rourkela and Bhilai", sources: [dsp(2, "This is the third integrated Steel Plant of the then Hindustan Steel Limited to come up under public sector in India. The first two being Rourkela Steel Plant and Bhilai Steel Plant in that order")] },
  { label: "Why here", value: "coal fields, the Grand Trunk Road, the Kolkata-Delhi railway, Kolkata Port, power from DVC and water from the Durgapur Barrage", sources: [dsp(2, "Durgapur as location was selected because of its proximity to coal fields, the Grand Trunk Road, Calcutta Delhi main railway track, Calcutta Port, Power from DVC (Damodar Valley Corporation) and water from Durgapur Barrage on river Damodar.")] },
  { label: "Cost, at the start", value: "Rs 189.6 crore, of which Rs 17.36 crore for the township", sources: [dsp(3, "with an investment of Rs. 189.6 Crores including Rs. 17.36 Crores for township development")] },
  { label: "Land", value: "6,568 hectares acquired; the township covers 32 sq km in three zones, A, B and C", sources: [city(67, "a total of 6,568 hectares of land was acquired"), city(70, "The three zones – A, B and C – are spread over an area of 32 square kilometers"), on(SRC.about, "Durgapur Steel Plant Township is spread over a sprawling 40 sq. kms.")], differsAt: [1, 2], note: "The sources differ on the township: SAIL's book says 32 square kilometres; SAIL's plant page, its RTI manual and the Ministry's 2002 backgrounder say 40 sq km." },
  { label: "Initial capacity", value: "1 MT (million tonnes) of crude steel a year", sources: [on(SRC.about, "Plant started production with an initial crude steel capacity of 1 MPTA (million ton per annum) in 1959"), city(65, "it submitted its report for setting up a one-million-tonne plant at Durgapur")] },
  { label: "Unique in India", value: "the only maker of forged railway wheels and axles in the country", sources: [on(SRC.about, "only producer of Forged Railway Wheels & Axles in the country")] },
];

